{
  "name": "LCC25液晶控制器",
  "name_en": "LCC25 Liquid Crystal Controller",
  "manufacturer": "Thorlabs",
  "description": "Thorlabs LCC25 是一款用于驱动液晶模块的电子控制器，可设置两个输出电压，并按设定重复频率在两者之间切换；还可配置驻留时间、扫描增量和设置存储。它常用于实验室中对液晶器件进行稳定的电压驱动与动态切换控制。",
  "description_en": "The Thorlabs LCC25 is an electronic controller for liquid crystal modules. It can set two output voltages and alternate between them at a defined repetition rate, with related settings such as dwell time, sweep increment, and stored configurations. It is used in laboratories to drive and switch liquid crystal devices under controlled electrical conditions.",
  "tag_hints": [
    "liquid crystal controller",
    "dual-voltage switching",
    "repetition rate control",
    "dwell time control",
    "bench-top electronics",
    "Thorlabs"
  ],
  "actions": [
    {
      "action_name": "auto-default",
      "description": "恢复出厂设置",
      "description_en": "restore factory settings"
    },
    {
      "action_name": "auto-dwell",
      "description": "设置或获取驻留时间",
      "description_en": "set or get dwell time"
    },
    {
      "action_name": "auto-enable",
      "description": "设置或获取使能状态",
      "description_en": "set or get enable state"
    },
    {
      "action_name": "auto-extern",
      "description": "设置或获取外部控制模式",
      "description_en": "set or get external control mode"
    },
    {
      "action_name": "auto-frequency",
      "description": "设置或获取切换重复频率",
      "description_en": "set or get switching repetition frequency"
    },
    {
      "action_name": "auto-increment",
      "description": "设置或获取测试模式的电压增量",
      "description_en": "set or get the voltage increment for test mode"
    },
    {
      "action_name": "auto-max_voltage",
      "description": "设置或获取最大输出电压",
      "description_en": "set or get maximum output voltage"
    },
    {
      "action_name": "auto-min_voltage",
      "description": "设置或获取最小输出电压",
      "description_en": "set or get minimum output voltage"
    },
    {
      "action_name": "auto-mode",
      "description": "设置或获取工作模式",
      "description_en": "set or get operating mode"
    },
    {
      "action_name": "auto-remote",
      "description": "设置或获取远程控制模式",
      "description_en": "set or get remote control mode"
    },
    {
      "action_name": "auto-save",
      "description": "将当前参数保存到静态存储器",
      "description_en": "save current parameters to nonvolatile memory"
    },
    {
      "action_name": "auto-set_settings",
      "description": "设定当前设置要保存到的存储槽",
      "description_en": "define the memory slot used to save the current settings"
    },
    {
      "action_name": "auto-test_mode",
      "description": "运行测试模式，使输出电压按增量从最小值扫描到最大值",
      "description_en": "run test mode, sweeping the output voltage from the minimum to the maximum in defined increments"
    },
    {
      "action_name": "auto-voltage1",
      "description": "设置或获取输出电压1",
      "description_en": "set or get output voltage 1"
    },
    {
      "action_name": "auto-voltage2",
      "description": "设置或获取输出电压2",
      "description_en": "set or get output voltage 2"
    },
    {
      "action_name": "auto-name",
      "description": "获取设备名称和版本信息",
      "description_en": "get device name and version information"
    },
    {
      "action_name": "auto-get_settings",
      "description": "获取指定存储槽中的设置",
      "description_en": "get the settings stored in the specified memory slot"
    }
  ]
}

